WITH filtered AS (SELECT *, CAST(is_flagged AS INT) AS is_flagged_flag, CAST(is_flagged AS INT) AS is_flagged_flag_2 FROM transactions WHERE amount <= 3400), deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY is_flagged_flag ASC NULLS LAST, id ASC) AS dedup_rank FROM filtered QUALIFY dedup_rank = 1), scored AS (SELECT *, ROUND(amount / SUM(amount) OVER (PARTITION BY txn_type, account_id), 4) AS amount_share, SUM(is_flagged_flag_2) OVER w_grp AS is_flagged_flag_2_sum_30d, LEAD(is_flagged_flag_2, 1) OVER (ORDER BY txn_time ASC, id ASC) AS next_is_flagged_flag_2, SUM(is_flagged_flag) OVER w_grp_2 AS running_is_flagged_flag FROM deduped WINDOW w_grp AS (PARTITION BY txn_type, merchant ORDER BY CAST(txn_time AS BIGINT) ASC RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW), w_grp_2 AS (PARTITION BY merchant ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), with_windows AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, is_flagged_flag, is_flagged_flag_2, dedup_rank, amount_share, is_flagged_flag_2_sum_30d, next_is_flagged_flag_2, running_is_flagged_flag, ROW_NUMBER() OVER (PARTITION BY merchant ORDER BY is_flagged_flag_2_sum_30d DESC, id ASC) AS seq_no, ROW_NUMBER() OVER (ORDER BY amount DESC, id ASC) AS row_seq, AVG(next_is_flagged_flag_2) OVER (PARTITION BY account_id, txn_type ORDER BY dedup_rank ASC, id ASC ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS next_is_flagged_flag_2_avg_2 FROM scored), joined AS (SELECT s.*, p.opened_date, p.status, p.balance FROM with_windows s LEFT JOIN accounts p ON s.account_id = p.id), with_gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time ASC, id ASC) > INTERVAL '60' DAY THEN 1 ELSE 0 END AS new_group_flag FROM joined), islands AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY merchant ORDER BY txn_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps), with_dims AS (SELECT e.*, b.status AS account_status, b.balance AS account_balance, b.opened_date AS account_opened_date FROM islands e LEFT JOIN accounts b ON e.account_id = b.id) SELECT DATE_TRUNC('YEAR', opened_date) AS year_start, STDDEV_SAMP(amount) AS amount_stddev, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min, PERCENTILE_APPROX(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, MAX(txn_time) AS last_seen, MIN(txn_time) AS first_txn_time, COUNT(*) AS row_count FROM with_dims GROUP BY DATE_TRUNC('YEAR', opened_date)
